INSERT INTO faqs (question, answer, sort_order) VALUES
  ('Do I need an appointment?', 'Walk-ins are welcome, but booking reduces your waiting time.', 0),
  ('Do you accept HMOs?', 'Contact us with the name of your HMO and we''ll confirm whether we accept it.', 1),
  ('What should I bring?', 'Bring a valid ID, your HMO card if you have one, and any previous results or medicines you''re taking.', 2),
  ('Is my information private?', 'Yes. Your health information is kept confidential.', 3),
  ('What should I do in an emergency?', 'Go to the nearest hospital emergency unit immediately or call 112. Don''t use this website for emergencies.', 4);
